import{_ as n,o as i,c as t,ah as r}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse(`{"title":"Exklusiv-Interview: Dr. Magnus von Zitzewitz über die 'Kunst der Aneignung'","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/interview-zitzewitz.md","filePath":"logbuch/interview-zitzewitz.md"}`),s={name:"logbuch/interview-zitzewitz.md"};function a(u,e,d,l,h,o){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="exklusiv-interview-dr-magnus-von-zitzewitz-uber-die-kunst-der-aneignung" tabindex="-1">Exklusiv-Interview: Dr. Magnus von Zitzewitz über die &#39;Kunst der Aneignung&#39; <a class="header-anchor" href="#exklusiv-interview-dr-magnus-von-zitzewitz-uber-die-kunst-der-aneignung" aria-label="Permalink to &quot;Exklusiv-Interview: Dr. Magnus von Zitzewitz über die &#39;Kunst der Aneignung&#39;&quot;">​</a></h1><p><em>In unserer Reihe &#39;Hinter den Kulissen des Horten-Mysteriums&#39; sprachen wir mit Dr. Magnus von Zitzewitz, einem freischaffenden &#39;Luxus-Etymologen&#39; und Berater für diskrete Vermögensumschichtung. Ein Gespräch über Perlenketten, leere Kaufhäuser und die Elastizität der Wahrheit.</em></p><hr><p><strong>Frage:</strong> Dr. von Zitzewitz, Sie gelten als Kenner der Horten-Ära. Wie würden Sie Helmut Hortens Geschäftsstil in einem Wort beschreiben?</p><p><strong>Zitzewitz:</strong> (lacht trocken) Ein Wort? Das ist so, als würde man versuchen, einen 20-karätigen Diamanten als &#39;Kieselstein&#39; zu bezeichnen. Wenn ich wählen müsste: <em>Präzision</em>. Helmut stahl nicht einfach Kaufhäuser. Er... befreite sie von der Last einer komplizierten Geschichte. Er war ein chirurgischer Ästhet des Kapitals.</p><p><strong>Frage:</strong> Kritiker nennen es &#39;Arisierung&#39;. In unserem Drehbuch spielt Oliver Masucci einen Bankier, der das als &#39;Marktbereinigung&#39; feiert. Ist das zu hart?</p><p><strong>Zitzewitz:</strong> Masucci? Eine exzellente Wahl! Er hat dieses wunderbare, hungrige Glitzern in den Augen. Und nein, es ist nicht zu hart. Es ist die Sprache der Zeit. Man muss verstehen: Im Berlin der 30er Jahre war Moral eine Währung, die massiv an Wert verloren hatte. Horten war einfach der Erste, der auf eine neue Währung setzte: Den puren, destillierten Erfolg.</p><p><strong>Frage:</strong> Kommen wir zur Witwe, Heidi Horten. Ihr Erbe ist heute untrennbar mit politischen Spenden verbunden. Wie sehen Sie die Affäre um die &#39;Spendenstückelung&#39;?</p><p><strong>Zitzewitz:</strong> (spielt mit seiner Krawatte) Ach, die Politik! Wissen Sie, Heidi sah das nicht als Spenden. Sie sah es als... Abonnements auf Stabilität. Wenn man so viel besitzt wie sie, möchte man eben sicherstellen, dass die Welt da draußen so bleibt, wie man sie gerne hätte. Die Stückelung? Das ist lediglich kreative Buchführungskunst. Ein Pointillismus des Geldes. Viele kleine Punkte ergeben am Ende ein sehr schönes Bild für die ÖVP.</p><p><strong>Frage:</strong> Was ist das größte Geheimnis, das wir in der Mockumentary lüften müssen?</p><p><strong>Zitzewitz:</strong> Dass es am Ende gar nicht um das Geld ging. Es ging um die totale Abwesenheit von Reue. Und genau das wird August Diehl so meisterhaft spielen. Diese Stille nach dem Deal. Das ist das wahre Mysterium.</p><hr>',12)])])}const m=n(s,[["render",a]]);export{c as __pageData,m as default};
